public class CaptureFunctionDataTypesAction : DockingAction {

	private DataTypeManagerPlugin plugin;

	public CaptureFunctionDataTypesAction(DataTypeManagerPlugin plugin) : base("Capture Function Data Types", plugin.getName())
    {
		this.plugin = plugin;

		setPopupMenuData(new MenuData(new string[] { "Capture Function Data Types" }, null,
			"VeryLast"));

		setEnabled(true);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {

		if (plugin.getProgram() == null) {
			return false;
		}

		if (!(context is DataTypesActionContext)) {
			return false;
		}

		object contextObject = context.getContextObject();
		GTree gTree = (GTree) contextObject;
		TreePath[] selectionPaths = gTree.getSelectionPaths();
		if (selectionPaths.length != 1) {
			return false;
		}

		GTreeNode node = (GTreeNode) selectionPaths[0].getLastPathComponent();
//        if (node instanceof CategoryNode) {
//            setEnabled( ((CategoryNode)node).isModifiable() );
//        }

		return (node is ProgramArchiveNode) || (node is FileArchiveNode) ||
			(node is ProjectArchiveNode);
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		GTree gTree = (GTree) context.getContextObject();
		TreePath selectionPath = gTree.getSelectionPath();
		DataTypeStoreNode node = (DataTypeStoreNode) selectionPath.getLastPathComponent();
		if (!node.getDataTypeStore().isChangeable()) {
			informNotModifiable(node);
			return;
		}

		Program program = plugin.getProgram();
		AddressSetView currentSelection = plugin.getCurrentSelection();
		if (currentSelection == null || currentSelection.isEmpty()) {
			currentSelection = program.getMemory();
		}
		DataTypeManager manager = node.getDataTypeManager();
		PluginTool tool = plugin.getTool();
		CaptureFunctionDataTypesCmd cmd =
			new _Anon_CaptureFunctionDataTypesCmd_1(manager, currentSelection,
				new CaptureFunctionDataTypesListener());
		tool.executeBackgroundCommand(cmd, program);
	}

	private void informNotModifiable(DataTypeStoreNode node) {
		string message;
		if (node is ProgramArchiveNode) {
			message = "The program \"" + node.getName() + "\" isn't modifiable.";
		}
		else if (node is ProjectArchiveNode) {
			message = "The data type archive \"" + node.getName() + "\" isn't checked out.";
		}
		else if (node is ProjectArchiveNode) {
			message = "The data type archive \"" + node.getName() + "\" isn't open for editing.";
		}
		else {
			message = "The data type archive \"" + node.getName() + "\" isn't modifiable.";
		}
		Msg.showInfo(getClass(),
			plugin.getTool().getToolFrame(), "Cannot Capture Data Types", message);
	}

	internal class _Anon_CaptureFunctionDataTypesCmd_1 : CaptureFunctionDataTypesCmd
	{
		public _Anon_CaptureFunctionDataTypesCmd_1() : @base(manager, currentSelection,
				new CaptureFunctionDataTypesListener() {}


					/* @Override */
					public void captureFunctionDataTypesCompleted(
							CaptureFunctionDataTypesCmd command) {
						tool.setStatusInfo("Captured function data types to \"" +
							manager.getName() + "\".");
					}
				
	}

}
